'use strict';
// Writes tools/xtb/d3-data.js (the D3 tables d3.js needs) from the Fortran sources of simple-dftd3 and mctc-lib.
// The numbers are copied as text (only the "_wp" suffix removed), so nothing is rounded on the way.
//
//   git clone --depth 1 https://github.com/dftd3/simple-dftd3.git <dir>/simple-dftd3
//   git clone --depth 1 https://github.com/grimme-lab/mctc-lib.git <dir>/mctc-lib
//   node tools/xtb/d3-gen.js <dir> [maxZ = 86]
const fs = require('fs'), path = require('path'), { execSync } = require('child_process');

const dir = process.argv[2];
if (!dir) { console.error('usage: node tools/xtb/d3-gen.js <dir with simple-dftd3 and mctc-lib> [maxZ]'); process.exit(1); }
const MAXZ = +(process.argv[3] || 86);
const read = p => fs.readFileSync(path.join(dir, p), 'utf8');
const strip = s => s.split('\n').map(l => l.replace(/!.*$/, '')).join('\n'); // drop Fortran comments
const nums = s => (s.match(/[+-]?\d+\.\d*(?:[eEdD][+-]?\d+)?_wp/g) || []).map(t => t.replace(/_wp$/, '').replace(/^\+/, ''));
const commit = d => { try { return execSync('git -C ' + JSON.stringify(path.join(dir, d)) + ' log -1 --format=%h', { encoding: 'utf8' }).trim(); } catch (e) { return '?'; } };

// --- reference.f90: reference counts, reference CNs, the C6 table ---
const ref = strip(read('simple-dftd3/src/dftd3/reference.f90'));
const MAXREF = 7;
const nrefAll = ref.match(/number_of_references\(max_elem\)\s*=\s*\[([^\]]*)\]/)[1].replace(/&/g, '').split(',').map(s => +s.trim());
const cnText = nums(ref.match(/reference_cn\(max_ref, max_elem\)\s*=\s*reshape\(\[([\s\S]*?)\]\s*,/)[1]);
if (nrefAll.length !== 103 || cnText.length !== 103 * MAXREF) throw new Error('reference_cn/number_of_references parse');
// The C6 table is assigned in chunks: c6ab_view(a:b) = [ ... ]; collect them into one flat column-major array.
const flat = [];
for (const m of ref.matchAll(/c6ab_view\((\d+):(\d+)\)\s*=\s*\[([\s\S]*?)\]/g)) {
  const a = +m[1], b = +m[2], v = nums(m[3]);
  if (v.length !== b - a + 1) throw new Error('chunk ' + a + ':' + b + ' has ' + v.length);
  for (let k = 0; k < v.length; k++) flat[a - 1 + k] = v[k];
}
const npair = 103 * 104 / 2;
for (let k = 0; k < MAXREF * MAXREF * npair; k++) if (flat[k] === undefined) throw new Error('C6 table hole at ' + k);

// --- r4r2.f90: <r4>/<r2> per element ---
const r4 = strip(read('simple-dftd3/src/dftd3/data/r4r2.f90'));
const r4r2 = nums(r4.match(/r4_over_r2\(max_elem\)\s*=\s*\[([\s\S]*?)\]/)[1]);
// --- mctc-lib covrad.f90: covalent radii 2009 (Pyykkö), in Å ---
const cv = strip(read('mctc-lib/src/mctc/data/covrad.f90'));
const rcov = nums(cv.match(/covalent_rad_2009\(max_elem\)\s*=\s*aatoau\s*\*\s*\[([\s\S]*?)\]/)[1]);
if (r4r2.length !== 118 || rcov.length !== 118) throw new Error('r4r2/rcov parse');

// Compact C6: for each element pair zi >= zj (zi = 1..MAXZ, zj = 1..zi) only the nref(zi) x nref(zj) block,
// ordered as in Fortran (index of zi's reference fastest). Everything outside the block must be zero.
const out = [];
for (let zi = 1; zi <= MAXZ; zi++) for (let zj = 1; zj <= zi; zj++) {
  const ic = zj + zi * (zi - 1) / 2, base = MAXREF * MAXREF * (ic - 1), ni = nrefAll[zi - 1], nj = nrefAll[zj - 1];
  const row = [];
  for (let jr = 0; jr < MAXREF; jr++) for (let ir = 0; ir < MAXREF; ir++) {
    const t = flat[base + ir + MAXREF * jr];
    if (ir < ni && jr < nj) row.push(t); else if (+t !== 0) throw new Error('nonzero outside block ' + zi + ',' + zj);
  }
  out.push(row.join(','));
}

const refcn = [];
for (let z = 1; z <= MAXZ; z++) refcn.push('[' + cnText.slice((z - 1) * MAXREF, (z - 1) * MAXREF + nrefAll[z - 1]).join(',') + ']');
const txt = `'use strict';
// D3 dispersion tables for elements 1..${MAXZ}. Generated by tools/xtb/d3-gen.js; do not edit by hand.
// Sources: simple-dftd3 ${commit('simple-dftd3')} (src/dftd3/reference.f90, src/dftd3/data/r4r2.f90),
//          mctc-lib ${commit('mctc-lib')} (src/mctc/data/covrad.f90). Numbers copied as text.
// nref[z-1]: number of reference systems of element z; refcn[z-1]: their coordination numbers.
// r4r2[z-1]: <r4>/<r2> (d3.js takes sqrt(0.5 * r4r2 * sqrt(z)) as Fortran does); rcov[z-1]: covalent radius 2009, Å.
// c6: reference C6 (Hartree Bohr^6) for every pair zi >= zj in the order (1,1),(2,1),(2,2),(3,1)...: a block of
//     nref(zi) x nref(zj) numbers, zi's reference index running fastest.
module.exports = {
  maxZ: ${MAXZ},
  nref: [${nrefAll.slice(0, MAXZ).join(',')}],
  refcn: [${refcn.join(',')}],
  r4r2: [${r4r2.slice(0, MAXZ).join(',')}],
  rcov: [${rcov.slice(0, MAXZ).join(',')}],
  c6: [
${out.join(',\n')}
  ],
};
`;
const dest = path.join(__dirname, 'd3-data.js');
fs.writeFileSync(dest, txt);
console.log('wrote', dest, (txt.length / 1024).toFixed(1) + ' KB,', out.length, 'pairs,', out.reduce((s, r) => s + r.split(',').length, 0), 'C6 values');
